`,u.jsx(c.h2,{children:"Start with the work"}),`
`,u.jsx(c.p,{children:"A useful post can begin with a small, specific thing: a feature shipped, a decision made, or a problem still being worked through. It does not need to be a finished success story."}),`
`,u.jsx(c.p,{children:"Explain the context, show the decision, and share what happened next. The details are what make a story useful to another builder."}),`
`,u.jsx(c.h2,{children:"Share the process"}),`
`,u.jsx(c.p,{children:"A simple structure makes it easier to write consistently:"}),`
`,u.jsxs(c.ul,{children:[`
`,u.jsx(c.li,{children:"What were you trying to build?"}),`
`,u.jsx(c.li,{children:"What made it difficult?"}),`
`,u.jsx(c.li,{children:"What did you try, and what would you change?"}),`
`]}),`
`,u.jsxs(c.blockquote,{children:[`
`,u.jsx(c.p,{children:"The unfinished parts can be worth writing about, too."}),`
`]}),`
`,u.jsx(c.h2,{children:"Leave room to learn"}),`
`,u.jsx(c.p,{children:"A personal blog can be a record of evolving ideas. A short reflection on one concrete lesson is often more useful than an exhaustive guide."}),`
`,u.jsx(c.p,{children:"Use this page as a starting point for your own writing. The title, excerpt, and article are editable in a single MDX file."})]})}function Mh(d={}){const{wrapper:c}=d.components||{};return c?u.jsx(c,{...d,children:u.jsx(Vr,{...d})}):Vr(d)}const Hh=Object.freeze(Object.defineProperty({__proto__:null,default:Mh,meta:Eh},Symbol.toStringTag,{value:"Module"})),Th={slug:"danii-million-dollar-exit-starting-again",title:"He Made $1 Million in His 20s. Then He Lost Almost Everything.",excerpt:"From building his first B2B app as a teenager to a nearly $1 million exit, and then losing a huge part of it in crypto. This is Danii’s story of building, losing, and starting again.",category:"The Underdog Show",readingTime:"5 min",sample:!1,image:"/images/danii-million-dollar-underdog.jpg",imageAlt:"The Underdog Show thumbnail featuring Danii and mscode07: Made $1,000,000 at 20, then lost it all in crypto.",imageWidth:1671,imageHeight:941};function Cr(d){const c={a:"a",h2:"h2",p:"p",...d.components};return u.jsxs(u.Fragment,{children:[u.jsx(c.p,{children:"At one point, Danii had what many young founders dream about."}),`
`,u.jsx(c.p,{children:"He had built successful products."}),`
`,u.jsx(c.p,{children:"He had made serious money."}),`
`,u.jsx(c.p,{children:"And while still incredibly young, he had an exit worth close to $1 million."}),`
`,u.jsx(c.p,{children:"Today?"}),`
`,u.jsx(c.p,{children:"He works at a coffee shop."}),`
`,u.jsx(c.p,{children:"He makes coffee for customers during the day and continues building apps whenever he can."}),`
`,u.jsx(c.p,{children:"But this isn’t really a story about losing $1 million."}),`
`,u.jsx(c.p,{children:"It’s a story about what you do after you lose almost everything."}),`
`,u.jsx(c.p,{children:"For Episode 1 of The Underdog Show, I sat down with Danii (@denpoint1 on X) to understand his journey."}),`
`,u.jsx(c.p,{children:"And it started much earlier than I expected."}),`
`,u.jsx(c.h2,{children:"It Started With Sitting in a Restaurant for Hours"}),`
`,u.jsx(c.p,{children:"Danii started building when he was around 17."}),`
`,u.jsx(c.p,{children:"Instead of sitting at home trying to think of the “next billion-dollar startup idea,” he did something much simpler."}),`
`,u.jsx(c.p,{children:"He found a real business with a real problem."}),`
`,u.jsx(c.p,{children:"A restaurant."}),`
`,u.jsx(c.p,{children:"Before building his B2B product, he spent hours inside restaurants observing how they operated."}),`
`,u.jsx(c.p,{children:"How did employees work?"}),`
`,u.jsx(c.p,{children:"Where did they waste time?"}),`
`,u.jsx(c.p,{children:"What problems did restaurant owners face every day?"}),`
`,u.jsx(c.p,{children:"What could software actually improve?"}),`
`,u.jsx(c.p,{children:"He wasn’t building based on assumptions."}),`
`,u.jsx(c.p,{children:"He was watching the problem happen in front of him."}),`
`,u.jsx(c.p,{children:"That eventually turned into his first B2B application: a table-reservation product for restaurants."}),`
`,u.jsx(c.p,{children:"And that first business went on to generate around $40,000."}),`
`,u.jsx(c.p,{children:"For a teenager building his first serious product, that alone would have been an incredible story."}),`
`,u.jsx(c.p,{children:"But things were only getting started."}),`
`,u.jsx(c.h2,{children:"Then Came the Game That Changed Everything"}),`
`,u.jsx(c.p,{children:"A few years later, Danii entered another chapter of his journey: mobile games."}),`
`,u.jsx(c.p,{children:"He built a game connected to the Telegram ecosystem and the events surrounding Telegram founder Pavel Durov."}),`
`,u.jsx(c.p,{children:"And then something crazy happened."}),`
`,u.jsx(c.p,{children:"The game took off."}),`
`,u.jsx(c.p,{children:"It reached roughly 1 million users within a few weeks."}),`
`,u.jsx(c.p,{children:"Eventually, Danii exited the project for an amount close to $1 million."}),`
`,u.jsx(c.p,{children:"Think about that for a second."}),`
`,u.jsx(c.p,{children:"He had gone from a teenager sitting inside restaurants trying to understand their problems…"}),`
`,u.jsx(c.p,{children:"to having a major exit while still in his early twenties."}),`
`,u.jsx(c.p,{children:"And there was another interesting part of his story."}),`
`,u.jsx(c.p,{children:"This happened before today’s AI coding boom."}),`
`,u.jsx(c.p,{children:"There was no asking an AI agent to build the application."}),`
`,u.jsx(c.p,{children:"No one could generate an entire codebase from a prompt."}),`
`,u.jsx(c.p,{children:"He had to research, experiment, code, fail, fix things, and learn by himself."}),`
`,u.jsx(c.p,{children:"One source of inspiration he mentioned during our conversation was Y Combinator."}),`
`,u.jsx(c.p,{children:"He consumed their content and became obsessed with building things people actually wanted."}),`
`,u.jsx(c.p,{children:"Eventually, he did exactly that."}),`
`,u.jsx(c.p,{children:"But making money and knowing how to handle money are two very different skills."}),`
`,u.jsx(c.h2,{children:"Then Everything Started Going in the Other Direction"}),`
`,u.jsx(c.p,{children:"Imagine getting that kind of money while you’re still extremely young."}),`
`,u.jsx(c.p,{children:"Suddenly, life changes."}),`
`,u.jsx(c.p,{children:"Danii talked openly about this part of his story."}),`
`,u.jsx(c.p,{children:"There was alcohol."}),`
`,u.jsx(c.p,{children:"There were expensive things."}),`
`,u.jsx(c.p,{children:"There were decisions he wouldn’t necessarily make today."}),`
`,u.jsx(c.p,{children:"And slowly, the money started disappearing."}),`
`,u.jsx(c.p,{children:"Then came crypto."}),`
`,u.jsx(c.p,{children:"Danii was already involved in the crypto world, but this time the market didn’t give him another success story."}),`
`,u.jsx(c.p,{children:"He lost a huge part of what he had left."}),`
`,u.jsx(c.p,{children:"The person who had once experienced a near-million-dollar exit was suddenly dealing with debt and trying to rebuild his life."}),`
`,u.jsx(c.p,{children:"And that’s the part of his story I found much more interesting than the $1 million."}),`
`,u.jsx(c.h2,{children:"What Do You Do After Losing Almost Everything?"}),`
`,u.jsx(c.p,{children:"It’s easy to talk about entrepreneurship when everything is going up."}),`
`,u.jsx(c.p,{children:"Revenue screenshots."}),`
`,u.jsx(c.p,{children:"User milestones."}),`
`,u.jsx(c.p,{children:"Funding announcements."}),`
`,u.jsx(c.p,{children:"Successful exits."}),`
`,u.jsx(c.p,{children:"But what happens when all of that disappears?"}),`
`,u.jsx(c.p,{children:"Danii returned home."}),`
`,u.jsx(c.p,{children:"His family and friends supported him through a difficult period. He borrowed money and started working again, this time not as the founder of a rapidly growing product, but in a coffee shop."}),`
`,u.jsx(c.p,{children:"Today, he works as a barista."}),`
`,u.jsx(c.p,{children:"And after his shifts?"}),`
`,u.jsx(c.p,{children:"He still builds."}),`
`,u.jsx(c.p,{children:"Apps."}),`
`,u.jsx(c.p,{children:"Experiments."}),`
`,u.jsx(c.p,{children:"New ideas."}),`
`,u.jsx(c.p,{children:"He is still trying."}),`
`,u.jsx(c.p,{children:"That’s what made me want to tell his story."}),`
`,u.jsx(c.p,{children:"Because losing money didn’t remove the thing that made him a builder in the first place."}),`
`,u.jsx(c.h2,{children:"Building From Russia Added Another Challenge"}),`
`,u.jsx(c.p,{children:"There was another side of Danii’s journey that we discussed during the podcast: building technology from Russia."}),`
`,u.jsx(c.p,{children:"He explained how the war and international restrictions affected parts of the Russian tech ecosystem and made accessing certain global products, payment systems, and business opportunities more difficult."}),`
`,u.jsx(c.p,{children:"For someone trying to build internet businesses for a global audience, those restrictions created another layer of difficulty."}),`
`,u.jsx(c.p,{children:"Yet Danii continued building."}),`
`,u.jsx(c.p,{children:"Not because there was a guarantee that another million-dollar exit was coming."}),`
`,u.jsx(c.p,{children:"There wasn’t."}),`
`,u.jsx(c.p,{children:"He simply wasn’t finished."}),`
`,u.jsx(c.h2,{children:"The $1 Million Isn’t the Most Interesting Part of His Story"}),`
`,u.jsx(c.p,{children:"When I first heard Danii’s story, the obvious headline was:"}),`
`,u.jsx(c.p,{children:"“Young founder makes nearly $1 million.”"}),`
`,u.jsx(c.p,{children:"But after talking to him, I don’t think that’s the most interesting part."}),`
`,u.jsx(c.p,{children:"It’s easy to admire someone at the top."}),`
`,u.jsx(c.p,{children:"I’m more interested in what they do when they’re back at the bottom."}),`
`,u.jsx(c.p,{children:"Danii built a business as a teenager."}),`
`,u.jsx(c.p,{children:"He experienced a massive win."}),`
`,u.jsx(c.p,{children:"He made mistakes."}),`
`,u.jsx(c.p,{children:"He lost a huge amount of money."}),`
`,u.jsx(c.p,{children:"He went into debt."}),`
`,u.jsx(c.p,{children:"He started working in a coffee shop."}),`
`,u.jsx(c.p,{children:"And he kept building."}),`
`,u.jsx(c.p,{children:"Maybe his next product succeeds."}),`
`,u.jsx(c.p,{children:"Maybe it doesn’t."}),`
