`,u.jsx(c.p,{children:u.jsx(c.strong,{children:"Bootstrapping."})}),`
`,u.jsx(c.p,{children:"Pasha discovered creators such as Marc Lou and the stories shared by Starter Story."}),`
`,u.jsx(c.p,{children:"Suddenly, indie hacking didn't look like some distant world reserved for Silicon Valley founders."}),`
`,u.jsx(c.p,{children:"Maybe he could do it too."}),`
`,u.jsx(c.p,{children:"There was only one problem."}),`
