`,u.jsx(c.p,{children:"A creative person."}),`
`,u.jsx(c.p,{children:"Someone interested in photography, visual design and abstract ideas."}),`
`,u.jsx(c.p,{children:"Programming felt like something for people who were naturally good at mathematics and logic."}),`
`,u.jsx(c.p,{children:"And that fear wasn't new."}),`
