`,u.jsx(c.p,{children:"But he kept going."}),`
`,u.jsx(c.p,{children:"And eventually he started building."}),`
`,u.jsx(c.h2,{children:"His First Product Failed Quietly"}),`
`,u.jsx(c.p,{children:"Before his current SaaS product, Pasha experimented with a real estate idea."}),`
`,u.jsx(c.p,{children:"The concept came from his photography background."}),`
`,u.jsx(c.p,{children:"Real estate agents need good property images, so he wondered whether AI could help improve those photos automatically."}),`
`,u.jsx(c.p,{children:"The idea made sense on paper."}),`
`,u.jsx(c.p,{children:"Building it was another story."}),`
